package org.eclipse.rdf4j.workbench.proxy;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.Mockito.mock;

import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;

import org.eclipse.rdf4j.repository.manager.RemoteRepositoryManager;
import org.eclipse.rdf4j.repository.manager.RepositoryManager;
import org.eclipse.rdf4j.workbench.base.AbstractServlet;
import org.eclipse.rdf4j.workbench.base.WorkbenchHtmlShell;
import org.eclipse.rdf4j.workbench.support.TestServletConfig;
import org.eclipse.rdf4j.workbench.util.TupleResultBuilder;
import org.eclipse.rdf4j.workbench.util.WorkbenchPageProtocol;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.mock.web.MockHttpServletResponse;

class WorkbenchServerIdentityTest {
	private static final String IDENTITY = "org.eclipse.rdf4j.workbench.serverIdentity";

	@Test
	void selectedManagerPublishesCanonicalCredentialFreeIdentity() throws Exception {
		String identity = identity("HTTPS://alice:secret@EXAMPLE.org:443/rdf4j-server/");
		assertThat(identity).isNotBlank()
				.startsWith("sha256:")
				.doesNotContain("alice", "secret", "example.org");
		assertThat(identity).isEqualTo(identity("https://example.org/rdf4j-server"));
		assertThat(identity).isNotEqualTo(identity("https://other.example/rdf4j-server"));
		assertThat(identity).isNotEqualTo(identity("https://example.org/RDF4J-server"));
		assertThat(identity("https://example.org/rdf4j-server?tenant=a"))
				.isNotEqualTo(identity("https://example.org/rdf4j-server?tenant=b"));
		assertThat(identity("https://example.org/rdf4j%2Fserver"))
				.isNotEqualTo(identity("https://example.org/rdf4j/server"));
	}

	@Test
	void localManagersUseTheirCanonicalDirectory(@TempDir File directory) throws Exception {
		String expected = identity(directory.toURI().toString());
		assertThat(expected).isNotBlank();
		assertThat(expected).isEqualTo(identity(directory.toURI().toString().replaceFirst("^file:", "FILE:")));
		assertThat(expected).isEqualTo(identity(Path.of(directory.toString(), ".").toUri().toString()));
		assertThat(expected).isNotEqualTo(identity(new File(directory, "other").toURI().toString()));
	}

	@Test
	void localIdentityDistinguishesLiteralPlusFromEncodedSpace(@TempDir Path tempDir) throws Exception {
		Path plus = Files.createDirectory(tempDir.resolve("repository+data"));
		Path space = Files.createDirectory(tempDir.resolve("repository data"));
		String plusUrl = plus.toUri().toString();

		assertThat(identity(plusUrl)).isEqualTo(identity(plusUrl.replace("+", "%2B")));
		assertThat(identity(plusUrl)).isNotEqualTo(identity(space.toUri().toString()));
	}

	@Test
	void localIdentityRejectsNonlocalFileAuthority(@TempDir Path tempDir) {
		String remote = tempDir.toUri().toString().replaceFirst("^file:/+", "file://remote.example/");
		assertThatThrownBy(() -> identity(remote)).hasRootCauseInstanceOf(IOException.class);
	}

	@Test
	void configuredManagerUrlFormsRemainSupported() throws Exception {
		for (String server : new String[] { "http://rdf4j_server:8080/rdf4j-server",
				"https://rädf.example/rdf4j-server", "http://[::1]:8080/rdf4j-server" }) {
			RepositoryManager manager = new WorkbenchServlet().createRepositoryManager(server);
			try {
				assertThat(manager).isInstanceOf(RemoteRepositoryManager.class);
				assertThat(((RemoteRepositoryManager) manager).getLocation()).hasToString(server);
			} finally {
				manager.shutDown();
			}
			assertThat(identity(server)).isNotBlank().startsWith("sha256:");
		}
		assertThat(identity("http://RDF4J_SERVER:8080/rdf4j-server/"))
				.isEqualTo(identity("http://rdf4j_server:8080/rdf4j-server"));
	}

	@Test
	void shellAndPageDataCarryResolvedIdentity() throws Exception {
		MockHttpServletRequest request = new MockHttpServletRequest();
		request.setContextPath("/workbench");
		request.setAttribute(IDENTITY, "sha256:server-a");
		MockHttpServletResponse shell = new MockHttpServletResponse();
		WorkbenchHtmlShell.write(request, shell, TestServletConfig.withParams("graph"), "graph");
		assertThat(shell.getContentAsString()).contains("data-workbench-server-identity=\"sha256:server-a\"");

		request.addHeader("Accept", WorkbenchPageProtocol.ACCEPT);
		MockHttpServletResponse page = new MockHttpServletResponse();
		new PageServlet().write(request, page);
		assertThat(page.getContentAsString()).contains("\"server-identity\":\"sha256:server-a\"");
	}

	private static String identity(String server) throws Exception {
		WorkbenchServlet servlet = new WorkbenchServlet() {
			@Override
			protected RepositoryManager createRepositoryManager(String param) {
				return mock(RepositoryManager.class);
			}
		};
		servlet.init(TestServletConfig.withParams("workbench", "default-path", "/repositories", "server", server));
		MockHttpServletRequest request = new MockHttpServletRequest();
		servlet.service(request, new MockHttpServletResponse());
		return (String) request.getAttribute(IDENTITY);
	}

	private static class PageServlet extends AbstractServlet {
		void write(MockHttpServletRequest request, MockHttpServletResponse response) throws Exception {
			TupleResultBuilder builder = getTupleResultBuilder(request, response, response.getOutputStream());
			builder.start("value");
			builder.end();
		}
	}
}
